template:
% 参数由系统自动注入：\def\radius{3} \def\showcenter{1} \def\showradius{1} \def\showdiameter{0}
% 视觉归一化：把圆直径缩放到 6（单位由 coordScale 决定），保证图形视觉大小稳定。
\pgfmathsetmacro{\figscale}{3 / \radius}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  \coordinate (O) at (0,0);
  \coordinate (A) at (\radius,0);
  \coordinate (B) at (-\radius,0);
  % 圆
  \draw[thick] (O) circle [radius=\radius];
  % 直径 AB（含右端 A、左端 B，优先于半径展示）
  \ifnum\showdiameter>0
    \draw[thick] (A) -- (B);
    \fill (A) circle [radius=1.6pt];
    \fill (B) circle [radius=1.6pt];
    \node[above right=3pt] at (A) {$A$};
    \node[above left=3pt] at (B) {$B$};
  \fi
  % 半径 OA（未画直径时才单独画）
  \ifnum\showdiameter=0
    \ifnum\showradius>0
      \draw[thick] (O) -- (A);
      \fill (A) circle [radius=1.6pt];
      \node[above right=3pt] at (A) {$A$};
    \fi
  \fi
  % 圆心 O
  \ifnum\showcenter>0
    \fill (O) circle [radius=1.6pt];
    \node[below left=3pt] at (O) {$O$};
  \fi
\end{tikzpicture}
